+const MIN_PORT = 1;
+const MAX_PORT = 65535;
+
+function parsePort(text: string, item: string): number {
+  if (!/^\d+$/.test(text)) {
+    throw new Error(`invalid port "${text}" in item "${item}"`);
+  }
+  const n = Number(text);
+  if (n < MIN_PORT || n > MAX_PORT) {
+    throw new Error(`port ${n} is outside ${MIN_PORT}-${MAX_PORT}`);
+  }
+  return n;
+}

